package dev.metallicarts.test;
import dev.metallicarts.MetallicArts;
import dev.metallicarts.allomancy.*;
import dev.metallicarts.arts.*;
import dev.metallicarts.domain.*;
import dev.metallicarts.economy.*;
import dev.metallicarts.equipment.*;
import dev.metallicarts.feruchemy.*;
import dev.metallicarts.network.ContactIntent;
import dev.metallicarts.registry.ModRegistries;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.Vec3;
import java.util.*;
public final class RequestedGameplayGameTest {
 private static void burn(ServerPlayer p,Metal metal,int tick){AdvancedSystemsGameTest.grant(p,Art.ALLOMANCY,metal);p.setAttached(ModRegistries.SPIRITWEB,ReserveLedger.credit(p.getAttachedOrCreate(ModRegistries.SPIRITWEB),metal,1000000));AllomancyRuntime.request(p,AllomancyConfig.SUPPORTED.indexOf(metal),1,tick);AllomancyRuntime.prepare(p,tick);}
 @GameTest public void distanceWeakensRealForceAndOpposedInputsAreExplicit(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);var center=p.getBoundingBox().getCenter();var near=new ItemEntity(c.getLevel(),center.x+2,center.y,center.z,new ItemStack(Items.IRON_BLOCK));var far=new ItemEntity(c.getLevel(),center.x+16,center.y,center.z,new ItemStack(Items.IRON_BLOCK));near.setDeltaMovement(Vec3.ZERO);far.setDeltaMovement(Vec3.ZERO);MetalPhysics.apply(p,new MetalPhysics.Target(near.position(),near,100,false),1,true,AllomancyConfig.DEFAULT);MetalPhysics.apply(p,new MetalPhysics.Target(far.position(),far,100,false),1,true,AllomancyConfig.DEFAULT);c.assertTrue(near.getDeltaMovement().x>far.getDeltaMovement().x&&far.getDeltaMovement().x>0,"Real distant metal receives weaker impulse");c.assertTrue(AllomancyRuntime.netForce(3,Map.of(Metal.STEEL,1.0,Metal.IRON,1.0))==0,"Equal simultaneous Push/Pull cancels");c.assertTrue(AllomancyRuntime.netForce(1,Map.of(Metal.STEEL,1.0,Metal.IRON,4.0))==1&&AllomancyRuntime.netForce(2,Map.of(Metal.STEEL,4.0,Metal.IRON,1.0))== -1,"Explicit action wins regardless of the other active metal");c.succeed();}
 @GameTest public void everyStandardMetalExceptAluminumAndItsAlloyCanBeForced(GameTestHelper c){for(var metal:Metal.values()){boolean expected=metal!=Metal.ALUMINUM&&metal!=Metal.DURALUMIN;c.assertTrue(MetalPhysics.external(new ItemStack(EconomyContent.item(metal.id(),"coin")))==expected,"Physical material: "+metal);}var charged=AdvancedSystemsGameTest.mind(AdvancedSystemsGameTest.player(c),FeruchemicalAttribute.HEALTH,1000);c.assertTrue(MetalPhysics.external(charged),"Invested gold is still physical metal");var wearer=AdvancedSystemsGameTest.player(c);wearer.getInventory().setItem(0,AdvancedSystemsGameTest.mind(wearer,FeruchemicalAttribute.HEALTH,1000));ContactService.equip(wearer,0,0);var observer=AdvancedSystemsGameTest.player(c);observer.teleportTo(wearer.getX()-2,wearer.getY(),wearer.getZ());c.assertTrue(MetalPhysics.refresh(observer,new MetalPhysics.Target(wearer.position(),wearer,80,false),AllomancyConfig.DEFAULT).isPresent(),"A worn contacted mind makes its wearer a physical metal source");var golem=c.spawn(net.minecraft.world.entity.EntityType.IRON_GOLEM,new BlockPos(2,2,2));c.assertTrue(MetalPhysics.refresh(observer,new MetalPhysics.Target(golem.position(),golem,500,false),AllomancyConfig.DEFAULT).isPresent(),"A bare iron golem is metal even without armor");c.assertTrue(MetalMaterials.block(Blocks.IRON_ORE.defaultBlockState())&&MetalPhysics.external(new ItemStack(Items.NETHERITE_SWORD)),"Ores and metal tools are covered");c.succeed();}
 @GameTest public void connectedBlocksAreOneSourceAndNearbyMetalBehindThePlayerIsDiscovered(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);var a=c.absolutePos(new BlockPos(1,2,4));var b=a.east();c.getLevel().setBlock(a,Blocks.IRON_BLOCK.defaultBlockState(),3);c.getLevel().setBlock(b,Blocks.GOLD_BLOCK.defaultBlockState(),3);ConnectedMetals.clear();var first=MetalPhysics.blockTarget(p,a);var second=MetalPhysics.blockTarget(p,b);c.assertTrue(MetalPhysics.key(first).equals(MetalPhysics.key(second)),"Touching different metals form one source");p.setYRot(180);var found=MetalPhysics.nearby(p,AllomancyConfig.DEFAULT);c.assertTrue(found.stream().anyMatch(t->MetalPhysics.key(t).equals(MetalPhysics.key(first))),"Metal sight includes sources outside the aim direction");c.assertTrue(found.stream().filter(t->MetalPhysics.key(t).equals(MetalPhysics.key(first))).count()==1,"Connected source is deduplicated");c.succeed();}
 @GameTest public void tossedCoinAutomaticallySelectsAndOutOfRangeLockLastsTenSeconds(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);burn(p,Metal.STEEL,100);p.getInventory().setItem(0,new ItemStack(EconomyContent.item("steel","coin"),2));c.assertTrue(CoinProjectile.toss(p)&&AllomancyRuntime.selections(p).size()==1,"A real tossed coin automatically becomes selected");var target=AllomancyRuntime.selections(p).getFirst();target.entity().setPos(p.getX()+100,p.getY(),p.getZ());AllomancyRuntime.tick(p,101);c.assertTrue(MetalPhysics.refresh(p,target,AllomancyConfig.DEFAULT).isEmpty(),"Out-of-range lock cannot be forced");AllomancyRuntime.tick(p,300);c.assertTrue(AllomancyRuntime.selections(p).size()==1,"Selection survives 199 out-of-range ticks");AllomancyRuntime.tick(p,301);c.assertTrue(AllomancyRuntime.selections(p).isEmpty(),"Selection expires after a full 200 ticks");AllomancyRuntime.stop(p);c.succeed();}
 @GameTest public void allItemsAndWorkstationOutputsRespectSixtyFourAndLegacyCountsAreConserved(GameTestHelper c){for(var item:EconomyContent.ITEMS.values())c.assertTrue(new ItemStack(item).getMaxStackSize()<=64,"No registered item exceeds 64");var p=AdvancedSystemsGameTest.player(c);p.getInventory().clearContent();p.getInventory().setItem(0,new ItemStack(EconomyContent.item("steel","portion"),99));StackLimits.player(p);int total=0;for(int i=0;i<p.getInventory().getContainerSize();i++){var stack=p.getInventory().getItem(i);c.assertTrue(stack.getCount()<=64,"Legacy stack split safely");if(stack.is(EconomyContent.item("steel","portion")))total+=stack.getCount();}c.assertTrue(total==99,"No legacy material discarded");var pos=c.absolutePos(new BlockPos(2,1,2));c.getLevel().setBlock(pos,EconomyContent.TABLE.defaultBlockState(),3);var table=(dev.metallicarts.metallurgy.MetallurgyBlockEntity)c.getLevel().getBlockEntity(pos);var output=table.fit(List.of(new ItemStack(EconomyContent.item("steel","portion"),100)));c.assertTrue(output!=null&&output.stream().mapToInt(ItemStack::getCount).sum()==100&&output.stream().allMatch(s->s.getCount()<=64),"A batch of 100 uses multiple legal stacks");c.succeed();}
 @GameTest public void bendalloyStorageDrainsVisibleFoodAndTappingRefillsItWithoutCreatingEnergy(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);AdvancedSystemsGameTest.grant(p,Art.FERUCHEMY,Metal.BENDALLOY);p.setAttached(ModRegistries.BODY,BodyState.DEFAULT);p.getFoodData().setFoodLevel(16);p.getFoodData().setSaturation(5);p.getInventory().setItem(0,AdvancedSystemsGameTest.mind(p,FeruchemicalAttribute.NUTRITION,0));ContactService.equip(p,0,0);c.assertTrue(FeruchemyRuntime.act(p,new ContactIntent(2,0,0,1,3),100),"Store nutrition");FeruchemyRuntime.tick(p,101);c.assertTrue(p.getFoodData().getFoodLevel()==15&&p.getAttachedOrCreate(ModRegistries.BODY).nutrition()==385000,"One real food point surrendered with exact fractional remainder");c.assertTrue(FeruchemyRuntime.act(p,new ContactIntent(2,0,0,2,1),102),"Tap stored nutrition");for(int tick=103;tick<=105;tick++)FeruchemyRuntime.tick(p,tick);var ref=ContactService.equipment(p).item(0).get(ModRegistries.METALMIND);var asset=MetalmindLedger.get(c.getLevel().getServer()).resolve(ref.token());c.assertTrue(p.getFoodData().getFoodLevel()==16&&asset.charge()==0&&p.getAttachedOrCreate(ModRegistries.BODY).nutrition()==0&&p.getFoodData().getSaturationLevel()==5,"Exact stored nutrition restores visible hunger once");FeruchemyRuntime.stop(p);c.succeed();}
 @GameTest public void sphericalFieldsAffectTheCasterAndOtherPlayersVerticallyAndRestoreOnExit(GameTestHelper c){var owner=AdvancedSystemsGameTest.player(c);var visitor=AdvancedSystemsGameTest.player(c);burn(owner,Metal.CADMIUM,100);TemporalEngine.update(owner,AllomancyRuntime.powers(owner),100);var bubble=TemporalEngine.bubbles().stream().filter(b->b.owner()==owner).findFirst().orElseThrow();visitor.teleportTo(owner.getX(),owner.getY()+bubble.radius()-1,owner.getZ());TemporalPlayers.apply(owner);TemporalPlayers.apply(visitor);c.assertTrue(TemporalPlayers.localRate(owner)<1&&TemporalPlayers.localRate(visitor)<1,"Caster and another player above the center are slowed");visitor.teleportTo(owner.getX(),owner.getY()+bubble.radius()+1,owner.getZ());TemporalPlayers.apply(visitor);c.assertTrue(TemporalPlayers.localRate(visitor)==1&&!visitor.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED).hasModifier(MetallicArts.id("temporal_rate")),"Leaving removes the whole local player rate immediately");var points=TemporalEngine.sphere(bubble.center(),bubble.radius());c.assertTrue(points.stream().anyMatch(v->v.y>bubble.center().y+bubble.radius()*.9)&&points.stream().anyMatch(v->v.y<bubble.center().y-bubble.radius()*.9)&&points.stream().allMatch(v->Math.abs(v.distanceTo(bubble.center())-bubble.radius())<.0001),"Surface geometry is a full sphere");AllomancyRuntime.stop(owner);TemporalPlayers.clear(visitor);c.succeed();}
 @GameTest(maxTicks=100) public void automaticCoinLockSurvivesTheActualImpactEntityReplacement(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);p.setNoGravity(true);p.setInvulnerable(true);c.getLevel().setBlock(p.blockPosition().below(),Blocks.STONE.defaultBlockState(),3);burn(p,Metal.STEEL,c.getLevel().getServer().getTickCount());p.getInventory().setItem(0,new ItemStack(EconomyContent.item("steel","coin"),2));p.setXRot(90);c.assertTrue(CoinProjectile.toss(p),"Throw one real coin");c.succeedWhen(()->{var selected=AllomancyRuntime.selections(p);c.assertTrue(selected.size()==1&&selected.getFirst().entity() instanceof ItemEntity,"Impact retained the same physical coin as a selected dropped item");c.assertTrue(((ItemEntity)selected.getFirst().entity()).getItem().getCount()==1&&p.getMainHandItem().getCount()==1,"One coin remains in hand and one in world");AllomancyRuntime.stop(p);});}
 @GameTest public void playerItemUseClockAcceleratesInsideAndReturnsToNormalOutside(GameTestHelper c){var owner=AdvancedSystemsGameTest.player(c);var visitor=AdvancedSystemsGameTest.player(c);owner.setNoGravity(true);visitor.setNoGravity(true);burn(owner,Metal.BENDALLOY,100);TemporalEngine.update(owner,AllomancyRuntime.powers(owner),100);visitor.teleportTo(owner.getX()+1,owner.getY(),owner.getZ());TemporalPlayers.apply(visitor);visitor.getFoodData().setFoodLevel(10);visitor.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.BREAD,2));visitor.startUsingItem(net.minecraft.world.InteractionHand.MAIN_HAND);int before=visitor.getUseItemRemainingTicks();visitor.doTick();c.assertTrue(before-visitor.getUseItemRemainingTicks()==3,"Another player's item-use countdown advances at the configured triple rate inside the fast sphere");visitor.teleportTo(owner.getX()+20,owner.getY(),owner.getZ());TemporalPlayers.apply(visitor);before=visitor.getUseItemRemainingTicks();visitor.doTick();c.assertTrue(before-visitor.getUseItemRemainingTicks()==1,"Leaving immediately restores the ordinary item-use clock");visitor.stopUsingItem();AllomancyRuntime.stop(owner);TemporalPlayers.clear(visitor);c.succeed();}
}
